import { test, expect } from '@playwright/test';

test.describe('Checkout Form Validation', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the application
    await page.goto('https://www.saucedemo.com');

    // Login with standard_user
    await page.getByLabel('Username').fill('standard_user');
    await page.getByLabel('Password').fill('secret_sauce');
    await page.getByRole('button', { name: /login/i }).click();

    // Wait for inventory page to load
    await page.waitForURL('**/inventory.html');
  });

  test('should show postal code required error when submitting checkout form without postal code', async ({ page }) => {
    // Add backpack to cart
    await page.locator('[data-test="add-to-cart-sauce-labs-backpack"]').click();

    // Open cart
    await page.locator('.shopping_cart_link').click();

    // Wait for cart page to load
    await page.waitForURL('**/cart.html');

    // Click checkout button
    await page.locator('[data-test="checkout"]').click();

    // Wait for checkout page to load
    await page.waitForURL('**/checkout-step-one.html');

    // Fill in first name
    await page.locator('[data-test="firstName"]').fill('Saif');

    // Fill in last name
    await page.locator('[data-test="lastName"]').fill('Afzal');

    // Click continue without filling postal code
    await page.locator('[data-test="continue"]').click();

    // Verify error container is visible with correct message
    const errorContainer = page.locator('[data-test="error"]');
    await expect(errorContainer).toBeVisible();
    await expect(errorContainer).toContainText('Postal Code is required');
  });

  test('should allow form submission when all required fields are filled', async ({ page }) => {
    // Add backpack to cart
    await page.locator('[data-test="add-to-cart-sauce-labs-backpack"]').click();

    // Open cart
    await page.locator('.shopping_cart_link').click();

    // Wait for cart page to load
    await page.waitForURL('**/cart.html');

    // Click checkout button
    await page.locator('[data-test="checkout"]').click();

    // Wait for checkout page to load
    await page.waitForURL('**/checkout-step-one.html');

    // Fill in all required fields
    await page.locator('[data-test="firstName"]').fill('Saif');
    await page.locator('[data-test="lastName"]').fill('Afzal');
    await page.locator('[data-test="postalCode"]').fill('12345');

    // Click continue
    await page.locator('[data-test="continue"]').click();

    // Verify we proceed to next step (checkout-step-two)
    await page.waitForURL('**/checkout-step-two.html');

    // Verify no error is shown
    const errorContainer = page.locator('[data-test="error"]');
    await expect(errorContainer).not.toBeVisible();
  });

  test('should show error when first name is missing', async ({ page }) => {
    // Add backpack to cart
    await page.locator('[data-test="add-to-cart-sauce-labs-backpack"]').click();

    // Open cart
    await page.locator('.shopping_cart_link').click();

    // Wait for cart page to load
    await page.waitForURL('**/cart.html');

    // Click checkout button
    await page.locator('[data-test="checkout"]').click();

    // Wait for checkout page to load
    await page.waitForURL('**/checkout-step-one.html');

    // Fill in only last name and postal code
    await page.locator('[data-test="lastName"]').fill('Afzal');
    await page.locator('[data-test="postalCode"]').fill('12345');

    // Click continue without first name
    await page.locator('[data-test="continue"]').click();

    // Verify error container is visible
    const errorContainer = page.locator('[data-test="error"]');
    await expect(errorContainer).toBeVisible();
    await expect(errorContainer).toContainText('First Name is required');
  });
});
